require([
    "jquery",
    "validation",
    "mage/mage",
    "mage/adminhtml/grid"
], function(jQuery){

    //<![CDATA[
    gridOrdersCustomerJsObject = new varienGrid('gridOrdersCustomer',
     'http\u003A\u002F\u002Flocalhost\u003A7780\u002Fadmin\u002Freports\u002Freport_customer\u002Forders\u002F', 'page',
     'sort', 'dir',
     'filter');
    gridOrdersCustomerJsObject.useAjax = '';

        gridOrdersCustomerJsObject.doFilterCallback = validateFilterDate;
        var period_date_from = $('gridOrdersCustomer_period_date_from');
        var period_date_to = $('gridOrdersCustomer_period_date_to');
        period_date_from.adviceContainer =
         $('gridOrdersCustomer_period_date_from_advice');
        period_date_to.adviceContainer =
         $('gridOrdersCustomer_period_date_to_advice');

        var validateFilterDate = function() {
            if (period_date_from && period_date_to) {
                var valid = true;
                jQuery(period_date_from).add(period_date_to).each(function() {
                    valid = Validation.validate(this) && valid;
                });
                return valid;
            }
            else {
                return true;
            }
        }

    /* Overwrite function from switcher.phtml widget*/
    switchStore = function(obj) {
        if (obj.options[obj.selectedIndex].getAttribute('website') == 'true') {
            var selectionType = 'website';
        } else if (obj.options[obj.selectedIndex].getAttribute('group') == 'true') {
            var selectionType = 'group';
        } else {
            var selectionType = 'store';
        }
        var storeParam = obj.value ? selectionType + '/' + obj.value + '/' : '';
        if (obj.switchParams) {
            storeParam += obj.switchParams;
        }
        var formParam = new Array('gridOrdersCustomer_period_date_from',
         'gridOrdersCustomer_period_date_to',
         'gridOrdersCustomer_report_period');
        var paramURL = '';
        var switchURL = 'http\u003A\u002F\u002Flocalhost\u003A7780\u002Fadmin\u002Freports\u002Freport_customer\u002Forders\u002F'
        .replace(/(store|group|website)\/\d+\//, '');

        for (var i = 0; i < formParam.length; i++) {
            if ($(formParam[i]).value && $(formParam[i]).name) {
                paramURL += $(formParam[i]).name + '=' + escape($(formParam[i]).value) + '&';
            }
        }
        setLocation(switchURL + storeParam + '?' + paramURL);
    }

    //]]>

});
